  "ap-2012a-am-q28": {
    "explanation": "正解はエです。(A,B)の組合せにUNIQUE制約があるので、NULLでない同じ値の組を複数行に持つことはできません。エはA=AA01の行をAA02に更新し、既存の(AA02,BB01)と同じ組を作るため制約違反です。アは削除なので重複を作りません。イとウは制約列にNULLを含む挿入で、本問の前提では違反になりません。なお、NULLを含む一意制約の扱いにはDBMSや設定による差があるため、実装時は利用する製品の仕様を確認します。",
    "question": "R表に、(A, B)の2列で一意にする制約(UNIQUE 制約)が定義されているとき,R 表に対する SQL 文のうち、この制約に違反するものはどれか。ここで、R表には主キーの定義がなく、また、全ての列は値が決まっていない場合(NULL)もあるものとする。\n\n表 R\n\n| A | B | C | D |\n|:---:|:---:|:---:|:---:|\n| AA01 | BB01 | CC01 | DD01 |\n| AA01 | BB02 | CC02 | NULL |\n| AA02 | BB01 | NULL | DD03 |\n| AA02 | BB03 | NULL | NULL |",
    "choices": {
      "ア": "DELETE FROM R WHERE A = 'AA01' AND B = 'BB02'",
      "イ": "INSERT INTO R(A, B, C, D) VALUES ('AA01', NULL, 'DD01', 'EE01')",
      "ウ": "INSERT INTO R(A, B, C, D) VALUES (NULL, NULL, 'AA01', 'BB02')",
      "エ": "UPDATE R SET A = 'AA02' WHERE A = 'AA01'"
    },
    "hasImage": false,
    "imageUrls": []
  },
