    "question": "データモデルを解釈してオブジェクト図を作成した。解釈の誤りを適切に指摘した記述はどれか。ここで、モデルの表記には UML を用い、オブジェクト図の一部の属性の表示は省略した。\n\nデータモデル：顧客（顧客番号、顧客名、住所）1 ― * 注文（注文番号、注文日、注文数）* ― 1 商品（商品番号、商品名、価格）。* は0以上を表す。\nオブジェクト図：A商店は注文123456・123457、B産業は注文123459にリンク。注文123456（2017-03-18、注文数2）は47型テレビと2ドア冷蔵庫にリンク。注文123457（2017-03-18、注文数1）と123459（2017-03-20、注文数3）は2ドア冷蔵庫にリンク。ドラム式洗濯機にはリンクなし。",
