  "ap-2019a-am-q17": {
    "explanation": "正解はウの200Mバイトです。実行順はA、次にB・C、次にD・E、最後にFです。A実行中はAの1ファイルで50M、B・C実行中はA・B・Cの3ファイルで150Mです。B終了時にAを削除します。D・E実行中には、Dが参照するB、Eが参照するCに加えてD・E自身の新規ファイルがあり、4×50＝200Mになります。D・E終了でB・Cを削除した後、F実行中はD・E・Fの3ファイルで150M。最大は200Mです。先行ジョブのファイルは後続の開始時ではなく終了時に消える点が要点です。",
    "question": "ジョブ群と実行の条件が次のとおりであるとき、一時ファイルを作成する磁気ディスクに必要な容量は最低何Mバイトか。\n[ジョブ群] (図を参照)\n[実行の条件]\n(1) ジョブの実行多重度を2とする。\n(2) 各ジョブの処理時間は同一であり,他のジョブの影響は受けない。\n(3) 各ジョブは開始時に50Mバイトの一時ファイルを新たに作成する。\n(4) X → Y の関係があれば、ジョブ X の開始時に作成した一時ファイルは、直後のジョブYで参照し、ジョブYの終了時にその一時ファイルを削除する。直後のジョブが複数個ある場合には、最初に生起されるジョブだけが先行ジョブの一時ファイルを参照する。\n(5) X → Y,Z はジョブXの終了時に、ジョブY, ZのようにジョブXと矢印で結ばれる全てのジョブが、上から記述された順に優先して生起されることを示す。\n(6) X,Y → Z は先行するジョブX, Y両方が終了したときにジョブZが生起されることを示す。\n(7) ジョブの生起とは実行待ち行列への追加を意味し、各ジョブは待ち行列の順に実行される。\n(8) OSのオーバヘッドは考慮しない。\n\nジョブ群の矢印：A→B、A→C、B→D、B→E、C→E、D→F、E→F。Aの後続は上からB・C、Bの後続は上からD・E。EはBとCの両方、FはDとEの両方の終了を待つ。",
    "hasImage": false,
    "imageUrls": []
  },
