    "explanation": "正解はウです。偶数パリティでは、データ3ビットとcを合わせた1の個数を偶数にします。3入力のXORはデータ中の1が奇数個なら1、偶数個なら0になるので、c＝x1⊕x2⊕x3とすれば偶数になります。例えばデータ100にはc＝1、110にはc＝0を付けます。エはこの値を反転するため奇数パリティです。ア・イは最初にANDを使っており、1の個数の偶奇を表しません。",
    "question": "3ビットのデータX1, X2, X3に偶数パリティビットを付加する回路はどれか。\n\n各選択肢の回路は入力 x1、x2、x3 をそのまま出力し、さらに次の論理式でパリティビット c を生成する。記号・はAND、＋はOR、⊕はXOR、¬はNOTを表す。",
