    "question": "ASP 利用方式と自社開発の自社センター利用方式(以下“自社方式”という)の採算性を比較する。次の条件のとき, ASP 利用方式の期待利益(効果額一費用)が自社方式よりも大きくなるのは、自社方式の初期投資額が何万円を超えたときか。ここで、比較期間は5年とする。\n\n[条件]\n・両方式とも、システム利用による効果額は500万円/年とする。\n・ASP 利用方式の場合,初期費用は0円,利用料は300万円/年とする。\n・自社方式の場合,初期投資額は定額法で減価償却計算を行い、5年後の残存簿価は0円とする。また、運用費は100万円/年とする。\n・金利やその他の費用は考慮しないものとする。",
