  "fe-2009a-am-q2": {
    "explanation": "浮動小数点表示a＝f×r^eでは、値の有効な数字の部分fを仮数、小数点位置を変える倍率の底rを基数、その累乗の数eを指数と呼びます。したがってアが適切です。例えば1234を1.234×10^3と表すと、仮数は1.234、基数は10、指数は3となり、各役割が分かります。コンピュータ内部では基数を2とする表現も使われますが、名称の対応は変わりません。イ・ウ・エはこの三つの役割を入れ替えています。仮数は数字の精度、指数は表せる値の大きさの範囲に関係すると整理できます。"
  },
  "fe-2009a-am-q3": {
    "explanation": "原典の後置表記は「EF－G÷CD－AB＋÷＋」です。左から読むと、EF－でE－Fを作り、その後のG÷で(E－F)÷Gになります。続くCD－はC－D、AB＋はA＋Bで、それらの後の÷によって(C－D)÷(A＋B)を作ります。最後の＋で二つの結果を加えるため、通常の式は((E－F)÷G)＋((C－D)÷(A＋B))となりウです。演算子は直前にできた二つの値へ作用します。減算と除算では先に現れた値を左側に置くため、取り出す順序を逆にしないことが重要です。",
    "question": "逆ポーランド表記法（後置表記法）で、“EF－G÷CD－AB＋÷＋”と表現される式はどれか。",
    "choices": {
      "ア": "((A＋B)＋(C－D))÷G－(E÷F)",
      "イ": "((A＋B)÷(C－D))＋G÷(E－F)",
      "ウ": "((E－F)÷G)＋((C－D)÷(A＋B))",
      "エ": "((E－F)÷G)÷((C－D)＋(A＋B))"
    }
  },
  "fe-2009a-am-q5": {
    "explanation": "スタックは後入れ先出しなので、popでは最後にpushしたデータを取り出します。底から順に内容を書くと、push 1で[1]、push 2で[1,2]、最初のpopで2を取り出して[1]です。次に3と4を入れると[1,3,4]となり、二回目のpopで4を取り出して[1,3]に戻ります。5を入れて[1,3,5]とし、最後のpopで5を取り出すので、残るのは1と3でアです。途中で取り出した値は2、4、5であり、これらを残存データと取り違えないように、操作ごとにスタックの内容を更新します。"
  },
  "fe-2009a-am-q7": {
    "explanation": "オブジェクト指向では、データとそのデータを扱うメソッドを一つのまとまりとして捉えます。内部のデータを外部から直接変更させず、公開した操作を通して扱うカプセル化を説明したウが適切です。アは入力データがそろうと実行するデータフロー型、イは変数を介して状態を変更し命令を順に進める命令型、エは式や関数を評価して結果を求める関数型の特徴です。単に手続が存在することだけではなく、操作されるデータと操作を結び付け、内部構造を隠して外部との接点を定める点に注目します。"
  },
  "fe-2009a-am-q54": {
    "explanation": "品質管理では、要求された機能だけでなく、設計書や操作説明書など全ての成果物の品質も確認します。文書の誤りも開発・運用上の障害につながるので、ウが適切です。アは個々のサブシステムが正常でも、接続やデータ連携で不具合が起こり得るため誤りです。イの応答時間やバッチ処理時間も性能品質として管理対象になります。エも、市販製品と自社開発部分を組み合わせた状態で要求を満たすかを確認する必要があります。作成元や成果物の種類で対象を狭めず、システム全体が目的を満たすかを評価します。"
  },
  "fe-2009a-am-q74": {
    "explanation": "EDIはElectronic Data Interchangeの略で、受発注や請求などの企業間取引データを、当事者間で定めた形式や規約に従って電子的に交換する仕組みです。電子商取引におけるデータ交換という設問にはイが適切です。アのCAは公開鍵証明書を発行する認証局、ウのSSLは通信を保護するためのプロトコル、エのXBRLは財務報告などを電子的に記述する言語です。財務データの形式や通信の安全性はデータ交換にも関係しますが、商取引データを企業間で交換する仕組み自体を指す名称とは区別します。"
  },
  "fe-2009h-am-q6": {
    "explanation": "連結リストは、各要素が次の要素などへのポインタを持つデータ構造です。挿入位置が分かっていれば、前後のつながりを数個書き換えるだけで要素を挿入でき、配列のように後続要素をまとめて移動する必要がないため、エが適切です。アは対象に到達するまでポインタを順にたどる時間が掛かり、必ず短いとはいえません。イの全要素の移動は連結リストの削除では不要です。ウの添字による直接のランダムアクセスは配列の特徴です。挿入操作の時間と、挿入位置を探索する時間を分けて考えます。"
  },
  "fe-2009h-am-q7": {
    "explanation": "2分探索では整列済み配列の中央と比較し、目的の値が存在し得る側だけを残すため、比較するたびに探索範囲がほぼ半分になります。k回で範囲が約1個になるとすると、n/2^k≒1から2^k≒n、k≒log₂nとなり、アが適切です。例えば1024個なら、およそ10回程度の比較で絞り込めます。実際の最大回数には端点や端数による差がありますが、設問はおよその回数を問います。イのように対数をさらに半分にする理由はなく、ウのnは全件を順に調べる場合、エのn²は二重の全件処理などの規模です。"
  },
  "fe-2009h-am-q10": {
    "explanation": "シングルチップマイコンは、CPUに加えてメモリや入出力など、機器の制御に必要な機能を一つのチップへ集積したものです。外部のセンサの情報を取り込み、機器へ制御信号を出すための入出力機能を内蔵するエが適切です。ROMだけでなく作業用のRAMも内蔵する構成があり、イの説明は適切ではありません。アのPCの主CPUやウの高速・大規模処理を主な特徴とするより、少ない部品で小型の組込み制御を実現しやすい点に特徴があります。CPU単体と、周辺機能までまとめたマイコンを区別します。"
  },
