    "question": "図の線上を、点Pから点Rを通って、点Qに至る最短経路は何通りあるか。\n\n〔図の格子〕\n横5区画、縦4区画の長方形で、縦横の全ての格子線がつながっている。左下Pを(0,0)、右方向をx、上方向をyとすると、R=(2,2)、右上Q=(5,4)。格子線上を移動する。",
