    "explanation": "正解はイです。部署側の多重度1..*は、1人の従業員が1以上の部署に所属することを表し、複数部署への所属も許します。従業員側の0..*は、1部署に所属する従業員が0人でもよいことを表します。したがってウとエは逆で、両者の総数が一致するというアの制約もありません。",
    "question": "UMLを用いて表した図の概念データモデルの解釈として、適切なものはどれか。\n\n〔UML図〕\n部署 ── 従業員（関連名：従業員が部署に「所属する」）。部署側の多重度は1..*、従業員側の多重度は0..*。",
