    "question": "製品 X及びYを生産するために2種類の原料 A, Bが必要である。製品1個の生産に必要となる原料の量と調達可能量は表に示すとおりである。製品XとYの1個当たりの販売利益が、それぞれ100円,150円であるとき、最大利益は何円か。\n\n〔原料／製品X1個の必要量／製品Y1個の必要量／調達可能量〕\nA／2／1／100\nB／1／2／80",
