    "explanation": "正解はエの12日です。開始から終了までの経路はA→B→E→H→Jが2+2+2+2+4=12日、A→C→F→I→Jが2+1+3+1+4=11日、A→D→Gが2+4+3=9日です。並行作業を含む全作業の完了には最長経路の12日が必要です。「最少所要日数」は経路の最小値9日を選ぶ意味ではありません。",
    "question": "アローダイアグラムの日程計画をもつプロジェクトの,開始から終了までの最少所要日数は何日か。\n\n〔全作業と先行関係〕\nA：2日、先行なし。B：2日、先行A。C：1日、先行A。D：4日、先行A。E：2日、先行B。F：3日、先行C。G：3日、先行D。H：2日、先行E。I：1日、先行F。J：4日、先行H・I。GとJが両方終了するとプロジェクト終了。",
