  "sc-2009h-am1-q8": {
    "explanation": "正解はイのNANDです。式の三つの項はそれぞれ(A,B)=(0,1)、(1,0)、(0,0)のとき1となるので、両方1の場合だけX=0となります。これはNOT(A・B)です。ANDは両方1だけ1、ORは両方0だけ0、NORは両方0だけ1なので、この真理値表とは異なります。",
    "question": "論理式 X＝NOT(A)・B＋A・NOT(B)＋NOT(A)・NOT(B) と同じ結果が得られる論理回路はどれか。ここで「・」は論理積、「＋」は論理和、NOTは否定を表す。各選択肢は入力AとBから出力Xを得る1個のゲートである。",
    "choices": {
      "ア": "AND（論理積）回路",
      "イ": "NAND（否定論理積）回路",
      "ウ": "OR（論理和）回路",
      "エ": "NOR（否定論理和）回路"
    },
    "hasImage": false,
    "imageUrls": []
  },
