    "explanation": "正解はアです。aはコード順に整列しているため中央との大小比較で範囲を半減する2分探索が適します。bは使用頻度順なのでコードの大小で半分に絞れず、頻出コードから調べる線形探索が適します。cはコードから格納位置を計算できる構成なのでハッシュ表探索が適します。表の並び方と位置決定方法に応じて選びます。",
    "question": "探索表の構成法を例とともに a~c に示す。探索の平均計算量が最も小さい探索手法の組合せはどれか。ここで、探索表のコードの空欄は表の空きを示す。\n\n〔探索表の構成と例〕\na：コード順に格納。上から120380、120381、120520、140140、空き、空き、空き、空き。\nb：コードの使用頻度順に格納。上から120381、140140、120520、120380、空き、空き、空き、空き。\nc：コードから一意に決まる場所に格納。上から空き、120381、空き、120520、140140、空き、120380、空き。\n各コードの隣に対応データを格納している。",
