  "sc-2010h-am1-q6": {
    "explanation": "正解はエです。各媒体の容量が同じなので、空きが最大とは現在の割当て総量が最小の媒体です。順に90をA、30をB、40をC、次の40をB、70をC、最後の30をBへ割り当てます。最終総量はA=90、B=30+40+30=100、C=40+70=110Mバイトなので、大きい順はC、B、Aです。",
    "question": "三つの媒体 A~Cに次の条件でファイル領域を割り当てた場合、割り当てた領域の総量が大きい順に媒体を並べたものはどれか。\n[条件]\n(1) ファイル領域を割り当てる際の媒体選択アルゴリズムとして、空き領域が最大の媒体を選択する方式を採用する。\n(2) 割当て要求されるファイル領域の大きさは、順に90,30,40, 40, 70, 30(Mバイト)であり、割り当てられたファイル領域は、途中で解放されない。\n(3) 各媒体は容量が同一であり、割当て要求に対して十分な大きさをもち、初めはすべて空きの状態である。\n(4) 空き領域の大きさが等しい場合には、A,B,C の順に選択する。",
    "hasImage": false,
    "imageUrls": []
  },
