  "sc-2011a-am1-q3": {
    "explanation": "正解はイです。衝突とはa mod nとb mod nが等しいことです。同じ余りrでa=pn+r、b=qn+rと表せるので、a−b=(p−q)nはnの倍数です。逆に差がnの倍数なら余りは一致します。例えばn=10でa=13,b=23なら両方のハッシュ値は3で、差−10は10の倍数です。",
    "question": "自然数をキーとするデータを、ハッシュ表を用いて管理する。キーx のハッシュ関数h(x)を h(x) = x mod n とすると、キーaとbが衝突する条件はどれか。ここで、nはハッシュ表の大きさで あり,x modnはxをnで割った余りを表す。",
    "hasImage": false,
    "imageUrls": []
  },
