    "explanation": "正解はアの11秒です。到着順かつ多重度1なのでAは時刻0〜5、Bは5〜11、Cは11〜14に実行されます。Cは時刻3に到着しているため、ターンアラウンドタイムは終了時刻14−到着時刻3=11秒です。C自身の処理3秒だけでなく待ち時間8秒も含み、システム開始からの14秒とは区別します。",
    "question": "ジョブの多重度が1で、到着順にジョブが実行されるシステムにおいて、表に示す状態のジョブA~Cを処理するとき、ジョブCが到着してから実行が終了するまでのターンアラウンドタイムは何秒か。ここで、OS のオーバヘッドは考慮しないものとする。\n\n〔ジョブ／到着時刻／単独実行時の処理時間：単位秒〕\nA／0／5\nB／2／6\nC／3／3",
