  "sc-2012a-am1-q2": {
    "explanation": "正解はエの1101です。受信語1100010に対する三つの検査値は順に(1+1+0+0) mod2=0、(1+1+0+1) mod2=1、(1+0+0+0) mod2=1です。第1式に含まれず第2・第3式の双方に含まれるビットはy₄だけなので、4ビット目を0から1へ直します。訂正語1101010の情報部分は1101です。",
    "question": "4ビットから成る情報ビットx1x2x3x4に対して、\n(x1+x2+x3+x5) mod 2=0\n(x1+x2+x4+x6) mod 2=0\n(x2+x3+x4+x7) mod 2=0\nを満たす冗長ビットx5x6x7を付加した符号x1x2x3x4x5x6x7を送信する。\n受信符号 y1y2y3y4y5y6y7が、送信符号と高々1ビットしか異ならないとき,\n(y1+y2+y3+y5) mod 2\n(y1+y2+y4+y6) mod 2\n(y2+y3+y4+y7) mod 2\nがそれぞれ0になるかどうかによって、正しい情報ビットx1x2x3x4を求めることが可能である。y1y2y3y4y5y6y7=1100010であるとき、正しい情報ビットはどれか。ここで、a mod bは、aをbで割った余りを表す。",
    "hasImage": false,
    "imageUrls": []
  },
