  "sc-2012a-am1-q6": {
    "explanation": "正解はイの約0.88です。福岡―大阪の回線0.9はどの経路でも必要です。大阪―東京は直通0.9と名古屋経由0.9²=0.81の並列なので、通常の独立故障モデルで1−(1−0.9)(1−0.81)=0.981です。全体は0.9×0.981=0.8829となります。二つの経路が福岡―大阪を共有しているので、福岡からの二経路を独立とみなしてはいけません。",
    "question": "図の回線網における福岡・東京間の回線の稼働率はおよそ幾らか。ここで、隣接するノード間の回線の稼働率は、全て0.9とする。\n\n〔全回線〕\n福岡―大阪、大阪―東京、大阪―名古屋、名古屋―東京。これ以外の回線はない。",
    "hasImage": false,
    "imageUrls": []
  },
