    "explanation": "正解はウです。B終了10日をダミー経由で待つため、C・D・Eは最早10日開始です。C→Gは40日かかりHは50日開始、全体は60日で終了します。Eは50日までに完了すればよいので最遅開始40日、最早開始10日との差は30日です。Dは40日に終わるため余裕10日でクリティカルではありません。Fも最遅40日開始でよく、10日は最早開始です。",
    "question": "図のアローダイアグラムから読み取れることのうち、適切なものはどれか。ここで、プロジェクトの開始日は0日目とする。\n\n〔作業：日数、先行関係〕\nA：5日、先行なし。B：10日、先行なし。C：20日、先行A・B。D：30日、先行A・B。E：10日、先行A・B。F：10日、先行B。G：20日、先行C。H：10日、先行D・E・F・G。原図のB終了→A終了点、E・F終了点→D・G終了点の破線は0日のダミー作業。",
