  "sc-2012a-am1-q20": {
    "explanation": "インシデント管理は、サービスの中断や品質低下が起きたとき、できるだけ早く正常な状態へ戻して業務への影響を小さくする活動です。したがってインシデントの解決とサービスの復旧を挙げたイが適切です。例えば根本原因がまだ確定していなくても、代替手段で業務を再開する対応が含まれます。ウの根本原因の究明やエの傾向分析による予防、アの問題の解決策の評価は、問題管理の側面が強い活動です。復旧を急ぐ活動と、再発を防ぐために原因を取り除く活動を区別して考えます。"
  },
