  "sc-2012a-am1-q27": {
    "explanation": "技術のSカーブは、初期には進歩が緩やかで、その後急速に発展し、成熟すると性能向上が頭打ちになるという技術の発展過程を表します。限界に近づくと別の技術へ移行することもあり、設問にはアが適切です。イの需要曲線は価格と需要量の関係、ウのバスタブ曲線は時間経過と故障率の関係、エのラーニングカーブは経験の蓄積と生産性やコストの変化を表します。どれも時間や成長に関係する場合がありますが、技術そのものの導入から成熟、次の技術への移行という対象に注目します。"
  },
