  "sc-2012h-am1-q11": {
    "explanation": "媒体障害ではデータベースを保存していたディスクなどが損傷し、元のデータが使えないため、まずバックアップコピーから復元します。その後、バックアップ取得後にコミットした更新をログで再実行し、確定済みの内容へ戻すロールフォワードが必要なのでエが適切です。アとウのロールバックは未確定の更新を取り消す操作で、失われた媒体の内容を再構成するものではありません。イはコミット済みだが未反映の更新の再実行だけを述べています。媒体障害では、その前提となるデータ本体の復元も必要な点が重要です。"
  },
