  "sc-2013a-am1-q6": {
    "explanation": "Aは三台の並列なので、稼働率は1−(1−a)^3となり単体のaを上回ります。Bは一台と並列二台を直列につなぐためa{1−(1−a)^2}で、括弧内が1未満なのでaより小さくなります。Cは一台の経路と二台直列の経路の並列で、1−(1−a)(1−a²)＝a＋a²(1−a)となりaを上回ります。したがってAとCのイです。0＜a＜1なのでa²(1−a)は正です。並列部分があるという理由だけで判断せず、システム全体で必ず通る単独装置があるかを見るとBの違いを把握できます。"
  },
