  "sc-2013a-am1-q16": {
    "explanation": "図は「組織」同士を親・子という役割で結び、両側が多となる関連を表しています。一つの組織に複数の親も複数の子も認められ、その数を大小関係で制限していないため、親の数が子より多い場合もあり、アが適切です。多重度だけから全組織に必ず子が存在するとはいえず、イは誤りです。同じ組織型がさらに親や子として関連できるため、ウの二段階限定も導けません。複数の親を持つネットワーク状の関係も排除していないのでエも不適切です。箱が一つでも組織の実体が一つという意味ではありません。"
  },
