  "sc-2013a-am1-q18": {
    "explanation": "日数を求めるので表の工数比ではなく期間比を使います。要件定義から内部設計までの期間比は0.25＋0.21＋0.11＝0.57で、全体期間は228÷0.57＝400日です。プログラム開発は0.11×400＝44日ですが半分が完了しているので残り22日です。後続のシステム結合は44日、システムテストは84日となり、残りは22＋44＋84＝150日でイです。現在までの228日に開発の半分22日を加えて250日、全体400日との差が150日とも確認できます。人数の配分を示す工数比と期間比を混同しない点が重要です。"
  },
  "db-2013a-am1-q18": {
    "explanation": "日数を求めるので表の工数比ではなく期間比を使います。要件定義から内部設計までの期間比は0.25＋0.21＋0.11＝0.57で、全体期間は228÷0.57＝400日です。プログラム開発は0.11×400＝44日ですが半分が完了しているので残り22日です。後続のシステム結合は44日、システムテストは84日となり、残りは22＋44＋84＝150日でイです。現在までの228日に開発の半分22日を加えて250日、全体400日との差が150日とも確認できます。人数の配分を示す工数比と期間比を混同しない点が重要です。"
  },
