  "sc-2013a-am2-q1": {
    "explanation": "RLOは文字の表示方向を右から左へ変更する制御文字です。これをファイル名に含めると、保存されている文字列の順序と画面で見える順序を変え、実行ファイルを文書などの別の拡張子に見せ掛けられるので、エが該当します。アは偽警告で不安をあおって購入を迫る手口、イは攻撃観測のためのおとりシステム、ウはSNMPによる監視イベントの通知です。RLOによってファイルの実体や本当の種類が変わるのではなく、利用者に見せる名前を偽装する点が本質です。表示された末尾だけで安全性を判断する危険があります。"
  },
  "sc-2013a-am2-q2": {
    "explanation": "XMLディジタル署名は署名対象を参照して指定でき、XML文書全体だけでなく特定のエレメントを対象にすることもできるので、アが適切です。エンベローピング署名は署名の要素内に署名対象を含む配置形式であり、イのように必ず複数の署名を付ける意味ではありません。署名に関する情報はXMLで表現するため、ウのCMSやエのASN.1をそのまま署名形式とする説明も異なります。何を署名するか、署名と対象をどこに置くか、署名情報をどの形式で記述するかという三つを分けて理解すると判断できます。"
  },
  "sc-2013a-am2-q11": {
    "explanation": "ルートキットは、不正侵入後に導入したプログラムや侵入の痕跡を隠し、攻撃者が活動を続けやすくするためのツール群です。OSの表示や機能などに介入してファイル、プロセス、通信の存在を見えにくくする場合があり、エが適切です。アのカーネルの脆弱性分析、イのウイルス感染の検査、ウのポートの調査はいずれも異なる役割です。名称にrootがあっても、単に管理者権限で使う正規の診断ツール全般を指すわけではありません。不正な存在を検知する側ではなく、存在を隠して検知を回避する側の機能に注目します。"
  },
  "sc-2013h-am1-q6": {
    "explanation": "フォールトアボイダンスは、設計や製造の品質管理などによって構成要素の信頼性を高め、故障を起こしにくくする考え方です。発生後の対処より予防に重点を置くエが適切です。アの安全な状態を保つ考え方はフェールセーフ、イの機能を縮小してサービスを続ける考え方はフェールソフトです。ウの故障の影響を訂正して外部へ出さない仕組みはフォールトマスキングに対応します。安全側へ停止すること、機能を落として継続すること、故障を利用者から見えなくすること、故障そのものを減らすことを分けて整理します。"
  },
