  "sc-2013h-am1-q7": {
    "explanation": "呼出し時点ではメイン側のXとYはいずれも2です。手続内のXは値渡しされたコピーなので、X＝X＋Yによって4になっても、メイン側のXは2のままです。次のY＝X＋Yでは、手続内で更新したXの4とYの2を加えて6となります。Yは参照呼出しのため、この更新はメイン側のYにも反映されます。したがって終了後はX＝2、Y＝6でイです。二つの代入は同時ではなく順に実行されるため、二行目で元のX＝2を使ってY＝4としないことと、ローカルなXの更新範囲に注意します。"
  },
