  "sc-2013h-am1-q11": {
    "explanation": "社員番号で一意になる社員表に氏名を置き、複数の言語を扱うプログラマの情報は別表に分けます。プログラマ表の主キーを社員番号と言語の組にし、社員番号を社員表への外部キーにすれば、同じ社員について言語ごとに複数行を記録できるのでエが適切です。アとイは社員番号だけを主キーにした一行に複数言語を持たせる問題があります。ウもプログラマ表の主キーが社員番号だけなので、一社員に一言語しか記録できません。ウとエは列名が同じですが、下線で指定された主キーの範囲が異なる点が決め手です。",
    "choices": {
      "ア": "社員（社員番号、氏名、職種、プログラム言語）。主キー：社員番号。",
      "イ": "社員（社員番号、氏名、プログラム言語）。主キー：社員番号。",
      "ウ": "社員（社員番号、氏名）。主キー：社員番号。プログラマ（社員番号、プログラム言語）。主キー：社員番号。外部キー：社員番号（社員表を参照）。",
      "エ": "社員（社員番号、氏名）。主キー：社員番号。プログラマ（社員番号、プログラム言語）。複合主キー：社員番号、プログラム言語。外部キー：社員番号（社員表を参照）。"
    }
  },
