  "sc-2013h-am1-q29": {
    "explanation": "マクシミン原理は、各案で最も悪い場合の利益を求め、その最小利益が最大の案を選びます。積極的投資の最小値は50万円、継続的投資は100万円、消極的投資は200万円なので、消極的投資を選ぶエが適切です。反対に最良の場合を重視するマクシマックスなら、各最大値500、300、400万円の中から積極的投資を選び、ウは誤りです。また、純粋戦略や混合戦略という区分だけで、景気の確率や選択基準なしに特定案を最適と断定できません。景気の見通しを勝手に仮定せず、原理に沿って表を読みます。"
  },
