  "sc-2013h-am2-q1": {
    "explanation": "APTは、特定の組織や情報などを目的に、複数の手段を使って継続的かつ執拗に行われる攻撃です。侵入や潜伏を気付かれにくくし、目的達成まで働き掛けるウが適切です。アはサービス妨害に手段と目的を限定しており、APT全体の説明にはなりません。イの興味本位の場当たり的な攻撃や、エの不特定多数への感染拡大も、標的と目的を定める特徴と異なります。高度な単一の攻撃技術の名前ではなく、メール、脆弱性悪用、認証情報の窃取などを組み合わせて長期に狙う性質を表す用語として理解します。"
  },
  "sc-2013h-am2-q2": {
    "explanation": "DNSSECは、DNSのリソースレコードに対するディジタル署名を検証し、応答データの出所の正当性と完全性を確認する仕組みなので、イが適切です。偽のレコードを正規の応答として受け入れる危険を減らしますが、問い合わせ内容を暗号化して秘密にする機能ではありません。アの再帰問い合わせの受付範囲の拡大はむしろ悪用の余地を広げ、ウのサーバ二重化は可用性対策です。エは共通鍵に基づくDNS更新要求の認証に関する説明で、リソースレコードを公開鍵による署名で検証するDNSSECと区別します。"
  },
  "sc-2014a-am1-q1": {
    "explanation": "正答はエです。カルノー図の中央の四つの1は、行ABが01又は11、列CDが01又は11の領域です。ここではAとCは変化してもB=1、D=1が共通なので、論理項はB・Dになります。残る上段両端の二つの1は、左右端を隣接としてまとめます。A=0、B=0、D=0が共通でCだけが変化するため、~A・~B・~Dです。この二項の論理和が図全体の1を覆います。イの第一項ではC=1の上段右端を覆えず、アとウも余分な1を含みます。",
    "question": "A、B、C、Dを論理変数とするとき、次のカルノー図と等価な論理式はどれか。ここで、・は論理積、+は論理和、~XはXの否定を表す。",
    "choices": {
      "ア": "A・B・~C・D + ~B・~D",
      "イ": "~A・~B・~C・~D + B・D",
      "ウ": "A・B・D + ~B・~D",
      "エ": "~A・~B・~D + B・D"
    }
  },
