  "sc-2014a-am1-q3": {
    "explanation": "正答はイです。V₁から近い頂点を順に確定すると、V₃へは1、V₂へはV₃を経由して1+1=2であり、直接の4より短くなります。V₄へはV₁→V₃→V₂→V₄で1+1+1=3です。そこからV₆へ進むと3+1=4、V₅へ進むと3+2=5となります。V₃からV₅への直接経路は1+5=6、V₂からV₅へも2+4=6なので、いずれも短縮できません。したがって対象三頂点の最短時間はV₄が3、V₆が4、V₅が5で、この順に並べます。",
    "question": "グラフに示される頂点V₁からV₄、V₅、V₆の各点への最短所要時間を求め、短い順に並べたものはどれか。ここで、グラフ中の数値は各区間の所要時間を表すものとし、最短所要時間が同一の場合には添字の小さい順に並べるものとする。"
  },
