  "sc-2014a-am1-q7": {
    "explanation": "正答はウです。各段はANDの後にNOTがあるのでNANDであり、交差した帰還線からX=NOT(S・Y)、Y=NOT(R・X)と表せます。最初はS=R=1、X=0、Y=1です。Sを0にすると上段はYに関係なくX=1となり、その1が下段へ戻るためY=NOT(1・1)=0になります。その後Sを1へ戻しても、上段にはY=0が入るのでX=NOT(1・0)=1のままです。下段もY=0を維持します。この回路は帰還によって状態を保持するため、最終値はX=1、Y=0です。"
  },
