  "sc-2014a-am1-q15": {
    "explanation": "正答はアです。WPA2で用いる代表的な暗号化・完全性保護の方式はCCMPで、その基礎となる共通鍵暗号がAESです。無線LANのデータを暗号化するアルゴリズムを問われているので、認証や鍵交換で利用する公開鍵暗号と混同しないことが重要です。RC4は旧来のWEPやWPAのTKIPで用いられたストリーム暗号です。ECCは楕円曲線に基づく公開鍵暗号技術、RSAも公開鍵暗号方式であり、この設問の無線データ暗号化方式には該当しません。WPA2とAESの対応を押さえます。"
  },
