  "sc-2014h-am2-q6": {
    "explanation": "正答はエです。ダイナミックパケットフィルタリングでは、通過を許可した通信の状態を記録し、その要求に対応する戻りのパケットかどうかを判断します。外部から届いたという理由だけで一律に許可せず、内部から開始した正当な通信への応答を動的に通すことができます。アのIPアドレス変換はNATの機能です。イの暗号化されたデータ部の復号や、ウのアプリケーション層の内容検査は、このフィルタリング方式だけで当然に実現される機能ではありません。要求と応答の対応及び通信状態を利用する点が判断の鍵です。"
  },
  "sc-2014h-am2-q8": {
    "explanation": "正答はイです。ICMP Floodは、大量のICMPパケットによって通信回線や対象機器の処理能力を消費させ、正規の通信を妨害するDoS攻撃です。pingが送るEcho要求はICMPを使用するため、イの大量の要求パケットによる過負荷が該当します。アはHTTP GETを繰り返すアプリケーション層の攻撃、ウはTCPの接続開始要求を使うSYN Floodです。エは大量に確立したTCP接続を保持させる方法であり、ICMPとは異なります。いずれも可用性を害しますが、用いるプロトコルで分類します。"
  },
  "sc-2015a-am1-q1": {
    "explanation": "正答はエです。(A∪B∪C)の補集合が空集合であることは、全体集合のどの要素もA、B、Cの少なくとも一つに属するという意味です。そこでAにもBにも属さない要素を考えると、その要素は必ずCに属さなければなりません。したがって~A∩~B⊆Cが成り立ちます。ド・モルガンの法則を使えば、条件を~A∩~B∩~C=∅と書き換えても同じ結論になります。A又はBに属する要素については、それだけで条件を満たせるのでCへの所属は保証されず、ア・イ・ウは導けません。",
    "question": "集合A、B、Cに対して、(A∪B∪C)の補集合が空集合であるとき、包含関係として適切なものはどれか。ここで、∪は和集合、∩は積集合、~XはXの補集合を表し、X⊆YはXがYの部分集合であることを表す。",
    "choices": {
      "ア": "(A∩B)⊆C",
      "イ": "(A∩~B)⊆C",
      "ウ": "(~A∩B)⊆C",
      "エ": "(~A∩~B)⊆C"
    }
  },
