  "sc-2017a-am1-q5": {
    "explanation": "正答はアです。MTBFは平均故障間隔で、正常に稼働する時間の長さを表し、MTTRは故障後の平均修復時間です。エラーログがあれば、故障時の状況や原因、影響範囲を調査しやすくなり、修理や復旧作業に要する時間を短縮できます。したがってMTTRの改善に直接役立ちます。ビット誤り訂正や命令再試行は、一時的な誤りを回復してシステムの故障へ発展することを抑えます。予防保守も故障の発生を減らす方向の対策です。故障しにくくする対策か、故障してから直すまでを速める対策かで区別します。"
  },
