  "sc-2017a-am1-q6": {
    "explanation": "正答はイの実行可能状態です。プリエンプションは、より優先度の高いタスクの実行などのために、OSが実行中のタスクからCPUの使用権を取り上げることです。取り上げられたタスクは処理を続ける準備ができているので、CPUの再割当てを待つ実行可能状態に移ります。待ち状態は入出力の完了やイベントの発生など、CPU以外の条件が満たされるのを待つ状態であり異なります。また、処理が完了したわけでも休止させたわけでもありません。CPUさえ割り当てられれば再開できる点を押さえます。"
  },
