  "sc-2017a-am1-q7": {
    "explanation": "正答はウです。排他的論理和XORは、入力の一方が0なら他方をそのまま出力し、一方が1なら他方を反転して出力します。したがってX=A XOR G、Y=B XOR Gとすれば、G=0でX=A、Y=B、G=1でX=~A、Y=~Bとなります。アはG=0でX=0、Y=1に固定され、イはG=1で両出力が1に固定されます。エもG=0でXが0、G=1でYが0になるので条件を満たしません。原図のウは上下ともXORであり、制御入力Gを二つのゲートに共通で与えています。",
    "question": "入力G=0のときはX=A、Y=Bを出力し、G=1のときはX=~A、Y=~Bを出力する回路はどれか。ここで、~は否定を表す。",
    "choices": {
      "ア": "X=AND(A,G)、Y=NAND(B,G)",
      "イ": "X=OR(A,G)、Y=OR(B,G)",
      "ウ": "X=XOR(A,G)、Y=XOR(B,G)",
      "エ": "X=AND(A,G)、Y=AND(B,NOT G)"
    }
  },
