  "sc-2017a-am1-q15": {
    "explanation": "正答はアです。WAFはWeb Application Firewallの略で、Webアプリケーションとの通信内容を検査し、SQLインジェクションなどの攻撃に当たる要求を検知・遮断します。IPアドレスやポートだけでなく、HTTPのパラメータなどアプリケーション層の内容を扱う点が特徴です。イのPC内のブラウザへの攻撃監視、ウのOSへの不正ログイン監視、エのファイルのマルウェア検査は主たる役割ではありません。WAFの導入だけで全ての脆弱性がなくなるわけではなく、アプリケーション自体の修正も必要です。"
  },
