  "sc-2017h-am1-q7": {
    "explanation": "正答はイです。原図の上側のANDゲートには、Aを反転した~AとBが入り、下側のANDゲートにはAとBが入ります。最後のORで両者を合わせるので、F=(~A・B)+(A・B)です。共通因子BをくくるとF=(~A+A)・Bとなり、~A+Aは常に1なのでF=Bへ簡単化できます。B=0なら両ANDの出力は0、B=1ならAが0でも1でもどちらかのANDが1になります。したがってAの値に関係なく出力はBと同じです。配線の交差と接続点を区別し、各ゲートの入力から式を立てます。"
  },
