  "sc-2018a-am1-q8": {
    "explanation": "正答はイです。レンダリングは、形状、材質、光源、視点などで記述された仮想世界の情報から、ディスプレイに表示する画像を生成する処理です。三次元のモデル情報そのものと、それを見える画像へ変換する処理は区別します。アはカメラやセンサによる情報の認識、ウは現実と仮想の座標系の位置合わせです。エは物理法則に従って物の状態や位置を時間とともに変えるシミュレーションに当たります。状態の計算や座標の対応付けの結果を利用し、最終的に描画可能な画像へ変えるのがレンダリングです。"
  },
