  "sc-2018h-am1-q7": {
    "explanation": "正答はエです。15MHzの発振器をPLL1で8逓倍すると120MHzになります。図の分周器はPLL1の直後から分岐しているので、この120MHzを分周します。エの1/2¹⁰を選ぶと120,000kHz÷1024=117.1875kHzです。目標115kHzとの差は約1.90％であり、許容される109.25〜120.75kHzに入ります。ア・イ・ウではそれぞれ7,500、1,875、468.75kHzとなり範囲外です。CPUの240MHzは別枝のPLL2で更に2倍した値なので、分周器の入力に用いません。"
  },
