    "explanation": "正答はウで、25個です。図では製品A一個に部品Bを2個、部品Cを直接1個使用します。さらにB一個にもCを1個使用するため、A一個当たりに必要なCは、直接分1個とB経由の2×1個を合わせて3個です。Aを10個作ると総所要量は30個になります。Bの在庫は0なのでB経由の分を減らすことはできず、C自身の在庫5個だけを差し引いて30−5=25個を発注します。部品表の複数の階層に同じ部品が現れる場合は、それぞれの経路の数量を掛けて求め、全経路を合計してから在庫を充当します。"
