  "sc-2019a-am1-q6": {
    "explanation": "正答はウで、200Mバイトです。実行多重度2で処理時間も同じなので、A、次にBとC、次にDとE、最後にFの順になります。A実行中はAの一時ファイル一個、B・C実行中はA・B・Cの三個です。Aのファイルは最初の後続Bが終了すると削除されます。D・E実行中は、Dが参照するBのファイル、Eが参照するCのファイルに、新規のD・Eを加えた四個が存在します。D・E終了後にB・Cを削除し、F実行中はD・E・Fの三個です。最大四個なので50×4=200Mバイトとなります。",
    "question": "ジョブ群と実行の条件が次のとおりであるとき、一時ファイルを作成する磁気デ\nイスクに必要な容量は最低何Mバイトか。\n\n〔ジョブ群〕\nA→B、A→C、B→D、B→E、C→E、D→F、E→Fの順序関係がある。分岐ではBがCより上、DがEより上に描かれている。\n\n〔実行の条件]\n(1) ジョブの実行多重度を2とする。\n(2) 各ジョブの処理時間は同一であり,他のジョブの影響は受けない。\n(3) 各ジョブは開始時に50Mバイトの一時ファイルを新たに作成する。\n(4) X → Y の関係があれば、ジョブ X の開始時に作成した一時ファイルは、\n直後のジョブYで参照し、ジョブYの終了時にその一時ファイルを削除する。直\n後のジョブが複数個ある場合には、最初に生起されるジョブだけが先行ジョブの\n一時ファイルを参照する。\n(5) (X) → (Y, Z) はジョブXの終了時に、ジョブY, ZのようにジョブXと矢印で結\nばれる全てのジョブが、上から記述された順に優先して生起されることを示す。\n(6) (X, Y) → Z は先行するジョブX, Y両方が終了したときにジョブZが生起され\nることを示す。\n(7) ジョブの生起とは実行待ち行列への追加を意味し、各ジョブは待ち行列の順に\n実行される。\n(8) OSのオーバヘッドは考慮しない。",
    "hasImage": false,
    "imageUrls": []
  },
