  "sc-2019a-am1-q24": {
    "explanation": "評価点は、各項目の重みに4段階評価の点数を掛けて合計します。実績は省力化効果が5×3＝15点、期間の短縮が8×0＝0点、情報の統合化が12×1＝12点で、合計27点です。全て目標どおりの場合は各項目が3点なので、基準となる合計は（5＋8＋12）×3＝75点です。したがって目標達成度は27÷75×100＝36％となり、イです。27は達成度ではなく重み付きの評価点です。また、項目の重みを無視して評価点だけを平均すると、重要度の違いが反映されません。",
    "question": "定性的な評価項目を定量化するために評価点を与える方法がある。表に示す 4段階評価を用いた場合、重み及び4段階評価の結果から評価されたシステム全体の目標達成度は、評価項目が全て目標どおりだった場合の評価点に対し,何%となるか。\n\n| 評価項目 | 重み | 評価結果 |\n|---|---:|---|\n| 省力化効果 | 5 | 目標どおり |\n| 期間の短縮 | 8 | 変わらず |\n| 情報の統合化 | 12 | 部分改善 |\n4段階評価点：3＝目標どおり、2＝ほぼ目標どおり、1＝部分改善、0＝変わらず。"
  },
