  "sc-2019h-am1-q18": {
    "explanation": "コスト効率指数CPIは、実際に完成した作業の予算上の価値EVを、実コストACで割って求めます。現時点では40÷60＝2/3であり、予算40万円相当の作業に60万円を使っています。同じ効率が続くなら、完成時総予算BAC100万円に対応する実コストはEAC＝BAC÷CPI＝100÷（2/3）＝150万円で、エです。残作業の予算価値60万円を同じ効率で実施する費用90万円と、既発生費用60万円を足しても150万円になります。PVは進捗計画の値であり、このコスト効率の計算には用いません。",
    "question": "ある組織では、プロジェクトのスケジュールとコストの管理にアーンドバリューマネジメントを用いている。期間 10日間のプロジェクトの、5日目の終了時点の状況は表のとおりである。この時点でのコスト効率が今後も続くとしたとき、完成時総コスト見積り (EAC) は何万円か。\n\n| 管理項目 | 金額（万円） |\n|---|---:|\n| 完成時総予算（BAC） | 100 |\n| プランドバリュー（PV） | 50 |\n| アーンドバリュー（EV） | 40 |\n| 実コスト（AC） | 60 |"
  },
