  "sc-2019h-am1-q26": {
    "explanation": "コアコンピタンスは、顧客に価値を提供し、他社との差別化や競争優位の源泉となる企業の中核的な能力です。選択肢では、競合他社よりも効率性が高い生産システムが、自社に蓄積された技術や運営ノウハウなどの能力に当たるため、イが適切です。アの事業分野の成長率、ウの競合状況は外部の事業環境を表します。エの市場シェアは競争の結果としての地位を表す指標であり、優位性を生み出す能力そのものではありません。「成果や市場環境」と「成果を生み出す自社の力」を区別します。"
  },
