  "sc-2019h-am1-q27": {
    "explanation": "オープンイノベーションは、自社内の知識や技術だけでなく、社外のアイディア・技術なども活用して新しい価値を生み出す取組です。社外からアイディアを募って新サービス開発に利用するアは、組織の境界を越えた知識の活用に当たります。イは社内の部門間協力であり、外部との連携は示されていません。ウは物流の改善、エは自社製品の情報発信ですが、それだけでは社外の知識を取り込んだ革新とはいえません。単に情報を公開することや、社内で新製品を作ることとは区別します。"
  },
