  "sc-2019h-am2-q1": {
    "explanation": "CRLは、認証局が発行する証明書失効リストです。秘密鍵の漏えいや証明内容の変更などにより、有効期限を迎える前に利用を停止した証明書を識別するため、その証明書のシリアル番号を掲載します。従ってエが適切です。公開鍵そのものを並べる一覧ではありません。また、単なる有効期限切れは証明書に記載された有効期間から判断できます。署名が正しく、有効期間内に見える証明書でも、途中で失効している場合があるため、利用時にはCRLやOCSPなどによって失効状態を確認します。"
  },
  "sc-2019h-am2-q2": {
    "explanation": "OCSP（Online Certificate Status Protocol）は、ディジタル証明書の失効状態をオンラインで問い合わせるためのプロトコルで、ウが正しいです。利用者は証明書を識別する情報をOCSPレスポンダに送り、失効しているかどうかなどの応答を得ます。証明書失効リストCRLを取得して調べる方法と区別しましょう。OCSPは証明書の状態を確認する仕組みであり、秘密鍵の再発行や証明書更新の作業進捗を管理するものではありません。また、クライアントとレスポンダ間で通信相手用の鍵交換を行う仕組みでもありません。"
  },
  "sc-2019h-am2-q17": {
    "explanation": "ステートフルインスペクションは、通信セッションの状態を記録し、新たに届いたパケットがその状態と整合するかを確認する方式です。IPアドレスやポート番号を個々のパケットだけで判定する方式に加えて、過去の通信との関係を判断材料にするため、エが適切です。例えば、内部から開始した通信に対する応答であるかを確認します。アはリバースプロキシとして動作するWeb向けの検査、イはアプリケーションごとのプロキシ、ウはコネクションを中継するゲートウェイの説明です。いずれも状態を追跡するパケット検査という本問の特徴とは異なります。"
  },
  "sc-2019h-am2-q18": {
    "explanation": "隠れ端末問題は、複数の端末が同じアクセスポイントとは通信できる一方、端末同士では電波が届かず、相手の送信を検出できない状況で生じます。一方が送信中でも他方は空いていると判断して送信し、アクセスポイントでフレームが衝突するため、イが適切です。アのSSIDの通知設定やウの接続先変更を指すものではありません。エの送信中の衝突検出が難しいという無線通信の性質だけでは、端末同士が相手のキャリアを検出できないという隠れ端末固有の状況を説明していません。"
  },
  "sc-2020a-am1-q2": {
    "explanation": "ウは、どの文字の符号も他の文字の符号の先頭部分にならないため、区切り記号なしで一意に復号できます。平均符号長は0.5×1＋0.3×2＋0.1×3＋0.1×3＝1.7ビットです。エも一意に復号できますが、全て2ビットなので平均2ビットとなり、ウの方が短くなります。アは00をcともaaとも読めるため不適切です。イも010がbの01とaの0、又はaの0とcの10の二通りに読めます。短さだけでなく、元の文字列を曖昧なく復元できることが必須です。"
  },
