  "sc-2020a-am1-q10": {
    "explanation": "Aの回線は1Gビット/秒、Bは100Mビット/秒なので、同じ長さのデータを送る時間はBがAの10倍です。Aの片道伝送時間をt、ホスト処理時間をhとすると、Aでは2t＋h＝100、Bでは20t＋h＝820となります。差を取ると18t＝720で、t＝40ミリ秒となりエです。処理時間も100−2×40＝20ミリ秒と求まり、Bの往復800ミリ秒と合わせて820ミリ秒になります。往復の伝送時間を含むため、単に回線速度の差だけで100と820の比を取らないことが要点です。",
    "question": "図のようなネットワーク構成のシステムにおいて、同じメッセージ長のデータをホストコンピュータとの間で送受信した場合のターンアラウンドタイムは、端末 A では100ミリ秒,端末Bでは820ミリ秒であった。上り、下りのメッセージ長は同じ長さで、ホストコンピュータでの処理時間は端末 A, 端末 Bのどちらから利用しても同じとするとき、端末 Aからホストコンピュータへの片道の伝送時間は何ミリ秒か。ここで、ターンアラウンドタイムは、端末がデータを回線に送信し始めてから応答データを受信し終わるまでの時間とし、伝送時間は回線速度だけに依存するものとする。\n\n〔ネットワーク構成〕\nホストコンピュータ ─（回線速度1Gビット/秒）─ 端末A\nホストコンピュータ ─（回線速度100Mビット/秒）─ 端末B"
  },
