  "pm-2020a-am1-q20": {
    "explanation": "逓減課金方式では、使用量が増えるにつれて追加使用量に対する単価が低くなります。縦軸が累計課金額の場合、総額は増え続けますが、グラフの傾きは徐々に緩やかになるのでウが適切です。単価が下がることと、支払う累計額そのものが減ることを区別します。アは使用量が増すほど累計額が減る図です。イは一定量まで比例し、その後は料金が増えない上限付きの図です。エは使用量が増えるほど傾きが急になっており、追加使用量に対する単価が高くなる逓増課金を表します。",
    "choices": {
      "ア": "使用量が増えると、累計課金額が折れ線状に減少するグラフ。",
      "イ": "原点から一定の傾きで累計課金額が増え、途中から水平となるグラフ。",
      "ウ": "原点から累計課金額が増え、途中で傾きが段階的に小さくなるグラフ。",
      "エ": "原点から累計課金額が増え、途中で傾きが段階的に大きくなるグラフ。"
    }
  },
