  "sc-2021a-am1-q2": {
    "explanation": "行と列の二方向にパリティを付けると、データが1ビットだけ反転した場合、そのビットを含む行と列の両方でパリティ不一致が起こります。不一致の行と列の交点を特定し、そのビットを反転すれば訂正できるため、アの1ビットです。2ビット以上では、同じ行や列の反転が打ち消し合ったり、複数の交点候補ができたりして、常に誤り位置を一意に決定できません。複数ビットの誤りを検出できる場合があっても、確実に訂正できるビット数とは異なります。",
    "question": "図のように 16 ビットのデータを 4×4の正方形状に並べ、行と列にパリティビットを付加することによって何ビットまでの誤りを訂正できるか。ここで、図の網掛け部分はパリティビットを表す。\n\n〔図：各行の末尾と最下行がパリティ〕\n| 行 | データ1 | データ2 | データ3 | データ4 | 行パリティ |\n|---|---:|---:|---:|---:|---:|\n| 1 | 1 | 0 | 0 | 0 | 1 |\n| 2 | 0 | 1 | 1 | 0 | 0 |\n| 3 | 0 | 0 | 1 | 0 | 1 |\n| 4 | 1 | 1 | 0 | 1 | 1 |\n| 列パリティ | 0 | 0 | 0 | 1 | — |"
  },
