  "sc-2021a-am1-q18": {
    "explanation": "元の図には、A→C→E→GとB→D→F→Hという流れに加え、Aの終了をFの開始条件にする依存関係があります。したがってFはAとDの両方が終わるまで開始できません。アローダイアグラムでは、Aの終点からDの終点へダミー作業を置けば、この条件を表せるのでイです。アにはA→Fの依存関係がなく、エではAの終了を待つのがFではなくHになります。ウにはイと同じ依存関係に加えてAからHへの余分なダミーがありますが、Aの終了は既にFの開始条件なので、そのダミーは不要です。",
    "question": "次のプレシデンスダイアグラムで表現されたプロジェクトスケジュールネットワーク図を、アローダイアグラムに書き直したものはどれか。ここで、プレシデンスダイアグラムの依存関係は全て FS 関係とする。\n\n〔元のプレシデンスダイアグラム〕\n開始→A→C→E→G→終了\n開始→B→D→F→H→終了\n追加の依存関係：A→F。全て終了後開始（FS）関係。",
    "choices": {
      "ア": "開始から上段A→C→E→G、下段B→D→F→Hへ分岐し終了で合流。上下段を結ぶダミーなし。",
      "イ": "アの構成に、Aの終点からDの終点（Fの始点）へのダミーを追加。",
      "ウ": "アの構成に、Aの終点からDの終点及びFの終点への二つのダミーを追加。",
      "エ": "アの構成に、Aの終点からFの終点（Hの始点）へのダミーを追加。"
    }
  },
