  "sc-2021a-am1-q23": {
    "explanation": "KPIは、最終目標に向けた業務の達成状況を途中で測るための重要業績評価指標です。図のcでは「在庫日数7日以内」「誤出荷率3％以内」と、改善活動を評価できる具体的な測定指標と目標値を設定しているため、ウが正解です。aの「物流コスト10％削減」は最終的な到達目標であるKGI、bの「在庫の削減」「誤出荷の削減」は目標達成に重要な要因であるCSFに対応します。MBOは目標管理の仕組みであり、cの指標設定そのものの名称ではありません。",
    "question": "物流業務において、10%の物流コストの削減の目標を立てて、図のような業務プロセスの改善活動を実施している。図中のcに相当する活動はどれか。\n〔図の内容〕物流コスト削減活動の開始→a（物流コスト10％削減）→b（在庫の削減、誤出荷の削減）→c（在庫日数7日以内、誤出荷率3％以内）→改善活動の実施→成果の計測と目標値とのギャップ分析→aへ戻る。"
  },
