  "sc-2021a-am1-q28": {
    "explanation": "エッジコンピューティングでは、データの発生源であるセンサや端末の近くに処理機能を配置します。遠方のクラウドへ全データを送ってから判断する場合に比べ、応答を速くしたり、集約・選別したデータだけを送って通信量を減らしたりできます。この特徴を述べたアが正解です。イはウェアラブル機器による計測、ウは複数計算機を組み合わせる分散処理の説明、エは環境中の光・熱・振動などから電力を得るエネルギーハーベスティングの説明です。"
  },
  "db-2021a-am1-q28": {
    "explanation": "エッジコンピューティングでは、データの発生源であるセンサや端末の近くに処理機能を配置します。遠方のクラウドへ全データを送ってから判断する場合に比べ、応答を速くしたり、集約・選別したデータだけを送って通信量を減らしたりできます。この特徴を述べたアが正解です。イはウェアラブル機器による計測、ウは複数計算機を組み合わせる分散処理の説明、エは環境中の光・熱・振動などから電力を得るエネルギーハーベスティングの説明です。"
  },
