  "sc-2021a-am1-q29": {
    "explanation": "マクシミン原理は、各案で起こり得る最悪の結果を求め、その中で最もよい案を選ぶ慎重な意思決定基準です。各株式の予想値上がり幅の最小値は、Aが10円、Bが5円、Cが5円、Dが－10円です。この最小値が最大なのはAなので、アが正解です。経済の成長が「低」の列だけを比較するのではなく、各行の高・中・低すべてから最小値を選びます。最大の利益だけを比べてDを選ぶ考え方や、発生確率を使う期待値の計算とは区別します。",
    "question": "いずれも時価100円の株式A~Dのうち、一つの株式に投資したい。経済の成長を高、中、低の三つに区分したときのそれぞれの株式の予想値上がり幅は、表のとおりである。マクシミン原理に従うとき、どの株式に投資することになるか。\n〔予想値上がり幅：円〕列は経済の成長「高・中・低」。A：20・10・15、B：25・5・20、C：30・20・5、D：40・10・－10。"
  },
  "db-2021a-am1-q29": {
    "explanation": "マクシミン原理は、各案で起こり得る最悪の結果を求め、その中で最もよい案を選ぶ慎重な意思決定基準です。各株式の予想値上がり幅の最小値は、Aが10円、Bが5円、Cが5円、Dが－10円です。この最小値が最大なのはAなので、アが正解です。経済の成長が「低」の列だけを比較するのではなく、各行の高・中・低すべてから最小値を選びます。最大の利益だけを比べてDを選ぶ考え方や、発生確率を使う期待値の計算とは区別します。",
    "question": "いずれも時価100円の株式A~Dのうち、一つの株式に投資したい。経済の成長を高、中、低の三つに区分したときのそれぞれの株式の予想値上がり幅は、表のとおりである。マクシミン原理に従うとき、どの株式に投資することになるか。\n〔予想値上がり幅：円〕列は経済の成長「高・中・低」。A：20・10・15、B：25・5・20、C：30・20・5、D：40・10・－10。"
  },
  "pm-2021a-am1-q29": {
    "explanation": "マクシミン原理は、各案で起こり得る最悪の結果を求め、その中で最もよい案を選ぶ慎重な意思決定基準です。各株式の予想値上がり幅の最小値は、Aが10円、Bが5円、Cが5円、Dが－10円です。この最小値が最大なのはAなので、アが正解です。経済の成長が「低」の列だけを比較するのではなく、各行の高・中・低すべてから最小値を選びます。最大の利益だけを比べてDを選ぶ考え方や、発生確率を使う期待値の計算とは区別します。",
    "question": "いずれも時価100円の株式A~Dのうち、一つの株式に投資したい。経済の成長を高、中、低の三つに区分したときのそれぞれの株式の予想値上がり幅は、表のとおりである。マクシミン原理に従うとき、どの株式に投資することになるか。\n〔予想値上がり幅：円〕列は経済の成長「高・中・低」。A：20・10・15、B：25・5・20、C：30・20・5、D：40・10・－10。"
  },
