  "sc-2021h-am1-q5": {
    "explanation": "各枝では装置2台が直列なので、枝の稼働率はx²です。この枝が2本並列にあり、両方とも停止したときだけシステムが停止するため、f(x)＝1－(1－x²)²＝2x²－x⁴となります。例えばx＝0.5ではf(x)＝0.4375で直線y＝xより下、x＝0.9では0.9639で直線より上です。またx＝0と1ではそれぞれ0と1になります。したがって、左側で直線を下回り、途中で交差して右側で上回るエのグラフが適切です。これは各装置の故障を独立として扱う計算です。",
    "question": "稼働率が x である装置を四つ組み合わせて、図のようなシステムを作ったときの稼働率を f(x) とする。区間0≦x≦1におけるy = f(x) の傾向を表すグラフはどれか。ここで、破線はy=xのグラフである。\n〔構成図〕装置2台を直列に接続した枝を2本作り、この2本の枝を並列に接続する。",
    "choices": {
      "ア": "(0,0)から(1,1)へ増加し、途中は直線y＝xより上にある曲線。",
      "イ": "(0,0)から(1,1)へ増加し、途中は直線y＝xより下にある曲線。",
      "ウ": "(0,0)から(1,1)へ増加し、左側で直線y＝xより上、途中で交差し右側で下になる曲線。",
      "エ": "(0,0)から(1,1)へ増加し、左側で直線y＝xより下、途中で交差し右側で上になる曲線。"
    }
  },
