  "sc-2021h-am1-q16": {
    "explanation": "命令網羅では、流れ図中の全ての処理命令を少なくとも1回実行すればよく、全経路の組合せを試す必要はありません。図は3分岐、2分岐、3分岐が順に並び、各段階の後で合流します。最初の3分岐を全て通るため最低3ケースが必要です。この3ケースで上段と下段をそれぞれ左・中央・右に振り分け、中段の左右も少なくとも1回ずつ通せば、全8個の処理を実行できます。よって最小数は3のアです。3×2×3＝18は全経路を網羅するときの数です。",
    "question": "あるプログラムについて、流れ図で示される部分に関するテストを、命令網羅で実施する場合,最小のテストケース数は幾つか。ここで、各判定条件は流れ図に示された部分の先行する命令の結果から影響を受けないものとする。\n〔流れ図〕上段は3本の分岐にそれぞれ処理命令が1個あり、その後合流する。中段は2本の分岐にそれぞれ処理命令が1個あり、その後合流する。下段は3本の分岐にそれぞれ処理命令が1個あり、その後合流して終了する。"
  },
