  "pm-2022a-am1-q1": {
    "explanation": "カルノー図の中央の4個の1は、行AB＝01・11、列CD＝01・11にあります。この範囲ではB＝1、D＝1が共通で、AとCは変化するため、項はB・Dです。残る上段の左右端の1は端同士が隣接しており、A＝0、B＝0、D＝0が共通でCが変化するので、項は¬A・¬B・¬Dです。両者の論理和を取ると¬A・¬B・¬D＋B・Dとなり、エが正解です。列の順序が00、01、11、10であることと、否定記号の付く変数に注意します。",
    "question": "A、B、C、Dを論理変数とするとき、次のカルノー図と等価な論理式はどれか。ここで、・は論理積、＋は論理和、¬XはXの否定を表す。\n〔カルノー図〕列CDは00、01、11、10の順。行AB＝00：1、0、0、1。行AB＝01：0、1、1、0。行AB＝11：0、1、1、0。行AB＝10：0、0、0、0。",
    "choices": {
      "ア": "A・B・¬C・D＋¬B・¬D",
      "イ": "¬A・¬B・¬C・¬D＋B・D",
      "ウ": "A・B・D＋¬B・¬D",
      "エ": "¬A・¬B・¬D＋B・D"
    }
  },
