  "sc-2022a-am1-q2": {
    "explanation": "過学習は、訓練データの特徴だけでなく偶然のばらつきやノイズにも強く適合し、未知のデータへの汎化性能が低くなる状態です。訓練データでは高精度なのに、未使用の検証データなどでは精度が下がるイが該当します。学習済みの知識を別領域に活用するアは転移学習、誤差を出力側から伝えて重みを調整するウは誤差逆伝播の説明です。エは報酬を用いた学習について述べていますが、過学習を表す現象ではありません。訓練精度だけで性能を判断しないことが重要です。"
  },
