  "sc-2022a-am1-q3": {
    "explanation": "衝突とは、異なるキーが同じハッシュ値に写ることです。aとbをnで割った余りが等しければ、a＝pn＋r、b＝qn＋rと書けるので、a－b＝(p－q)nとなり、差がnの倍数になります。逆に差がnの倍数なら、両者をnで割った余りは等しくなります。したがってイが正解です。例えばn＝10、a＝13、b＝3なら両方の余りは3です。和がnの倍数でも余りが同じとは限らず、nが差の倍数という条件は、倍数関係の向きが逆です。"
  },
