  "sc-2022a-am1-q7": {
    "explanation": "求める回路は、XとYがともに0、又はともに1のとき1となる一致回路で、式はXY＋¬X¬Yです。ウでは上側のNAND出力が¬(XY)、下側のNAND出力が¬(¬X¬Y)で、最後もNANDです。ド・モルガンの法則から、その出力はXY＋¬X¬Yとなり、条件を満たします。アはXYと¬X¬YをANDするので常に0、イはX・Y・その否定をORするので常に1です。エは(X＋Y)(¬X＋¬Y)となり、入力が異なる場合に1を出すため逆です。",
    "choices": {
      "ア": "XとYのAND、¬Xと¬YのANDを、最後にANDする回路。",
      "イ": "XとYのOR、¬Xと¬YのORを、最後にORする回路。",
      "ウ": "XとYのNAND、¬Xと¬YのNANDを、最後にNANDする回路。",
      "エ": "XとYのNOR、¬Xと¬YのNORを、最後にNORする回路。"
    }
  },
