  "sc-2022a-am1-q8": {
    "explanation": "3年後の顧客数は、毎年直前の年の1.2倍になるので、8,000×1.2³＝13,824人です。英大文字26種類を各桁に使うコードは、k桁で26のk乗通りを表せます。2桁では26²＝676通りで不足し、3桁なら26³＝17,576通りなので全員に異なるコードを割り当てられます。よって最少桁数は3、アが正解です。「毎年2割増」は元の8,000人の2割を毎年足すのではなく、前年の増加分にも次年の増加率が掛かる点に注意します。"
  },
