  "sc-2022a-am1-q18": {
    "explanation": "開始時刻を0日とすると、Aは6日後に終了します。AからBは終了－開始関係のリード2日なので、BはAの終了を2日前倒しして4日後に開始し、7日間の作業で11日後に終了します。BからCは開始－開始関係のラグ3日なので、CはB開始の3日後、つまり7日後に開始し、5日間で12日後に終了します。全作業の完了は最も遅いCの終了時点であり、12日のイが正解です。リードは前倒し、ラグは遅延であり、どの時点間の関係かを確認します。",
    "question": "図は、実施する三つのアクティビティについて、プレシデンスダイアグラム法を用いて、依存関係及び必要な作業日数を示したものである。全ての作業を完了するための所要日数は最少で何日か。\n〔図〕作業日数はA：6日、B：7日、C：5日。A→Bは終了－開始関係（リード2日）。B→Cは開始－開始関係（ラグ3日）。"
  },
