  "sc-2022a-am1-q22": {
    "explanation": "監査手続は、監査項目に対して判断の根拠となる十分かつ適切な監査証拠を得るための具体的な手順です。例えば担当者への質問、文書や記録の閲覧、現場での観察、処理の再実施などを組み合わせ、確認したい事項を検証します。したがってウが正解です。アは監査の計画や業務管理、イは監査結果の報告、エは監査実施体制の準備について述べています。いずれも監査業務には関係しますが、この用語が指す証拠収集・評価のための手順とは区別します。"
  },
