  "sc-2022a-am2-q1": {
    "explanation": "MACは、送受信者が共有する秘密の共通鍵とメッセージから生成します。受信者は同じ鍵でMACを再計算して受信した値と照合し、メッセージが改ざんされていないことを確認できるので、アが正解です。共通鍵を知らない第三者は検証できず、また受信者自身も同じ鍵でMACを生成できるため、MACだけでは第三者に「送信者が作成した」と証明できません。公開鍵はMAC生成の鍵ではなく、公開鍵で検証できるデジタル署名とは役割が異なります。"
  },
  "sc-2022a-am2-q2": {
    "explanation": "RAは登録局であり、証明書の申請者について本人確認などを行い、発行申請を承認又は却下する役割を担います。申請内容と本人の対応を確認するエが正解です。証明書に署名して発行するアはCA（認証局）の役割です。属性証明書の発行は属性認証局に関係し、失効情報の管理や証明書の有効性確認もRAの本人確認とは別の機能です。登録審査をするRAと、審査結果に基づいて証明書を発行するCAの責務を分けて理解すると整理できます。"
  },
  "sc-2022a-am2-q7": {
    "explanation": "リバースプロキシ方式では、利用者と対象Webサーバの間に置くプロキシが認証をまとめて扱います。通信がここを経由するため、冗長化しなければ障害で複数サービスが使えなくなる単一障害点になり得るエが正解です。SAMLはIdPとサービス側の間で認証結果などを交換する仕組みで、URL形式のIDを一人一つ発行することが本質ではありません。イのログイン画面への代行入力は代理認証方式、ウのサーバへのモジュール組込みはエージェント方式の説明です。"
  },
  "sc-2022a-am2-q9": {
    "explanation": "ISO/IEC 15408は、IT製品やシステムのセキュリティを評価するための共通基準です。求めるセキュリティ機能と、それが適切に実現されていることを確認する保証の枠組みを提供し、独立した評価結果を比較できるようにするため、アが正解です。27002は情報セキュリティ管理策に関する指針、27017はクラウドサービスのセキュリティ管理策に関する指針、30147はIoTの信頼性に関わるライフサイクル上の取組の規格です。製品のセキュリティ評価基準という対象で区別します。"
  },
  "sc-2022a-am2-q11": {
    "explanation": "クリックジャッキングは、利用者に見せる画面と実際にクリックさせる要素を重ね、意図しない操作をさせる攻撃です。X-Frame-Optionsを適切に設定すると、そのページが他サイトのフレーム内などに読み込まれるのを制限でき、攻撃の仕掛けを防ぐためエが正解です。HttpOnlyはスクリプトによるcookieの読取りを制限し、Secureはcookieを安全な通信に限って送信させます。Strict-Transport-SecurityはHTTPS利用を強制する仕組みで、いずれも画面の埋込み制限とは別です。"
  },
  "sc-2022a-am2-q13": {
    "explanation": "IPsecは、IPパケットをネットワーク層で保護するためのプロトコル群であり、ESPによって暗号化を提供できます。IPv6通信をネットワーク層で暗号化する条件に合うのはアです。PPPはポイント間の接続に用いるデータリンク層のプロトコルです。SSHは安全な遠隔ログインなどを提供し、TLSはTCPなどの上でアプリケーション通信を保護しますが、どちらもIPパケット自体をネットワーク層で暗号化する方式ではありません。IPv6を使うだけで自動的に暗号化されるわけでもありません。"
  },
  "sc-2022a-am2-q17": {
    "explanation": "プライバシーセパレータは、同じアクセスポイントに接続した無線端末同士の通信を遮断する機能です。例えば来訪者向けWi-Fiで、インターネットへの接続は提供しつつ他の利用者の端末に直接アクセスできないようにするため、イが正解です。アはアクセスポイントの識別子に関係し、ウはMACアドレスフィルタリングの説明です。エは電波の到達範囲や遮蔽による対策であり、この機能とは異なります。端末間を隔離することと、無線区間の暗号化・認証は別に考えます。"
  },
  "sc-2022h-am1-q8": {
    "explanation": "第1正規形では、一つの項目に複数値が入るような繰返しを除き、各属性を単一の値として扱うためcに対応します。第2正規形は第1正規形を満たし、非キー属性が複合キーの一部だけに依存する部分関数従属を除いた状態でありaです。第3正規形ではさらに、非キー属性を介して別の非キー属性がキーに依存する推移的関数従属を除くのでbです。したがって第1・第2・第3の順にc・a・bとなるウが正解です。正規化を進めるほど前段階の条件も満たします。"
  },
