  "sc-2022h-am1-q17": {
    "explanation": "完全化保守は、運用中のソフトウェアの性能や保守性などを改善する保守です。この設問では障害は発生しておらず、ソースコードの現状に合う仕様書を作り直すことで、理解や将来の変更を容易にする保守性改善なのでアに該当します。是正保守は発見された障害を直すもの、適応保守はOSなど利用環境の変化に対応するものです。予防保守は将来顕在化する潜在的な障害を事前に修正するものです。単に「将来のため」という理由だけで予防保守とは判断せず、作業の目的を見ます。"
  },
