    "question": "ある組織では、プロジェクトのスケジュールとコストの管理にアーンドバリューマネジメントを用いている。期間10日間のプロジェクトの,5日目の終了時点の状況は表のとおりである。この時点でのコスト効率が今後も続くとしたとき、完成時総コスト見積り (EAC) は何万円か。\n〔5日目終了時点：万円〕完成時総予算BAC＝100、プランドバリューPV＝50、アーンドバリューEV＝40、実コストAC＝60。"
