  "sc-2023a-am1-q7": {
    "explanation": "3入力の多数決では、A・B・Cのうち少なくとも2個が1のとき出力が1になります。AとB、BとC、AとCの各組をANDし、その結果をORすればよいので、Y＝AB＋BC＋ACです。この構成を持つアが正解です。イは各組のXORをORするため、例えば100でも1、111では0となり表と合いません。ウは各組のORを全てANDした結果の否定で、多数決の逆になります。エは3組のXORのANDを否定する構成で、111でも000でも1となるため不適切です。",
    "question": "真理値表に示す3入力多数決回路はどれか。\n〔真理値表：ABC→Y〕000→0、001→0、010→0、011→1、100→0、101→1、110→1、111→1。",
    "choices": {
      "ア": "AB、BC、ACをそれぞれANDで求め、その3出力をORする回路。",
      "イ": "A XOR B、B XOR C、A XOR Cの3出力をORする回路。",
      "ウ": "A OR B、B OR C、A OR Cの3出力のANDを取り、最後に否定する回路。",
      "エ": "A XOR B、B XOR C、A XOR Cの3出力のANDを取り、最後に否定する回路。"
    }
  },
