  "sc-2023a-am1-q9": {
    "explanation": "ロールフォワードの対象は、チェックポイント後にコミットし、更新を確定させる必要のあるT2とT5です。T1はチェックポイント前にコミット済みなので、その時点の状態に反映されています。障害時に未コミットなのはT3・T4・T6ですが、T3とT4はReadだけで更新していないため、データを元に戻す処理は不要です。Writeを含むT6だけをロールバックするので、アが正解です。コミット時刻だけでなく、各トランザクションが実際に更新を行うかも確認します。",
    "question": "DBMS をシステム障害発生後に再立上げするとき、ロールフォワードすべきトランザクションとロールバックすべきトランザクションの組合せとして、適切なものはどれか。ここで、トランザクションの中で実行される処理内容は次のとおりとする。\n〔処理内容〕T1・T2：Read 10回、Write 20回。T3・T4：Read 100回のみ。T5・T6：Read 20回、Write 10回。\n〔時間関係〕T1はチェックポイント前にコミット。T2はチェックポイント前に開始し、その後かつ障害前にコミット。T3はチェックポイント後に開始し障害時に未コミット。T4はチェックポイント前に開始し障害時に未コミット。T5はチェックポイント後に開始し障害前にコミット。T6はチェックポイント後に開始し障害時に未コミット。"
  },
