    "explanation": "変更前はA→B→E→H→Iが5＋8＋9＋4＋2＝28日で最長です。変更後はB終了後にE1の3日とE2の4日を並行実施し、両方の完了後にE3の2日を行うため、この部分は6日になります。したがってこの経路は25日に短縮しますが、A→B→D→Gの5＋8＋7＋7＝27日は変わりません。全体の完了は最長経路で決まるので、変更後は27日、短縮は28－27＝1日となりアが正解です。Eの短縮3日をそのまま全体の短縮量にしてはいけません。",
    "question": "プロジェクトのスケジュールを短縮したい。当初の計画は図1のとおりである。作業Eを作業 E1, E2, E3 に分けて、図2のとおりに計画を変更すると、スケジュールは全体で何日短縮できるか。\n〔図1〕作業と日数はA5、B8、C7、D7、E9、F5、G7、H4、I2。先行関係はA→B・C、B→D・E、C→F、D→G、E・F→H、H→I。GとIの両方で全体完了。\n〔図2〕EをBの後のE1（3日）とE2（4日）の並行作業に分け、両方の完了後にE3（2日）を実施する。HはE3とFの両方の完了後に開始。他の作業・関係は図1と同じ。"
