  "sc-2023a-am2-q1": {
    "explanation": "OSコマンドインジェクションは、外部入力がOSコマンドを実行する機能へ安全に扱われないまま渡され、攻撃者の意図したコマンドが実行される攻撃です。exec関数などを通じて不正なシェルスクリプトを実行させる設問はイに該当します。HTTPヘッダインジェクションはヘッダへの不正文字列混入、CSRFはログイン中の利用者に意図しないリクエストを送らせる攻撃、セッションハイジャックはセッションの乗っ取りです。入力の到達先がOSの実行機能である点に着目します。"
  },
  "sc-2023a-am2-q2": {
    "explanation": "TLS 1.3の暗号スイートは、通信データの暗号化と完全性保護を行うAEADと、鍵導出などに使うハッシュアルゴリズムの組を表すため、アが正解です。例えばTLS_AES_128_GCM_SHA256はAES-128-GCMとSHA-256を示します。鍵交換や署名方式は別に交渉されます。TLS 1.3ではAES-CBCを継続利用するというイは誤りで、標準化主体はIETFです。またサーバがクライアントの提示した候補から共通の暗号スイートを選び、双方が別々の方式を勝手に選ぶわけではありません。"
  },
  "sc-2023a-am2-q3": {
    "explanation": "VAは証明書の有効性確認を支援する機関で、利用者からの問合せに対して証明書の失効状態を返す役割を担います。例えばOCSPによるオンライン確認がこれに関係するため、ウが正解です。証明書に署名して発行するのはCA、申請者の本人確認を行って発行を承認するのはRAの役割です。属性証明書の発行もVAの失効状態確認とは別です。発行前の本人確認、証明書への署名、発行後の状態確認という段階で、RA・CA・VAを整理できます。"
  },
  "sc-2023a-am2-q4": {
    "explanation": "XML署名のデタッチ署名では、署名要素と署名対象が包含関係にない形で分離しています。別ファイルにする場合だけでなく、同じXML文書内で兄弟要素として配置することもできるので、アが正解です。エンベローピング署名は署名要素の中に対象データを含む形式であり、複数署名を意味するものではありません。逆に対象の内部に署名を置くのがエンベロープ署名です。XML署名の構造やアルゴリズム情報はXMLで記述し、CMSやASN.1による書式ではありません。"
  },
  "sc-2023a-am2-q7": {
    "explanation": "MITB攻撃では、PC内のブラウザに介入したマルウェアが、利用者の入力後に振込先などを書き換えることがあります。トランザクション署名は、別の信頼できるデバイスに取引情報を入力して、その内容に結び付いた認証値を生成・送信する仕組みなので、ウが正解です。送信途中で取引内容が変われば認証値と整合しなくなります。ログイン用の証明書やワンタイムパスワードだけでは、認証後に送金内容が改ざんされることを防げません。利用者の本人確認に加え、取引内容そのものを確認する点が重要です。"
  },
  "sc-2023a-am2-q8": {
    "explanation": "SAMLはXMLを基盤として、認証結果や利用者属性などのセキュリティ情報を異なるドメイン間で交換する標準であり、イが正解です。認証を担当するIdPの結果をサービス提供側が利用することで、複数サービスへのシングルサインオンを実現できます。アはリソースへのアクセス権を委譲するOAuthに近い説明ですが、それは本来認可の仕組みです。ウは従来のOpenID、エはXML自体の説明です。データ記述言語であるXMLと、その形式を使って認証連携を規定するSAMLを区別します。"
  },
  "sc-2023a-am2-q9": {
    "explanation": "CPSは認証局運用規程と呼ばれ、認証局が証明書を発行・管理する際に実際に採用する運用方法を詳細に記述した文書です。本人確認、発行、失効、鍵の管理、設備や要員の管理などの実務を説明するため、ウが正解です。証明書の所有者が出す宣言でも、発行手続の代行事業者や監査機関の一般的な運用文書でもありません。証明書をどの用途や要件で利用できるかを定める証明書ポリシーと、それを具体的にどう実施するかを述べるCPSを整理して理解します。"
  },
  "sc-2023a-am2-q17": {
    "explanation": "DBサーバを内部ネットワークへ移すと、運用管理PCとDBサーバのSSH通信はFWを通らなくなります。このため、以前のDMZ上のDBサーバに対するSSH許可ルールは不要となり、削除するイが正解です。インターネットからWebAPへのHTTPSは引き続き必要なのでアは削除できません。新たにFWを通るWebAPからDBへの通信は条件(2)のODBCであり、SSHを許可するウは誤りです。エのインターネットからのODBCも必要な通信ではなく、許可してはいけません。",
    "question": "セキュリティ対策として、次の条件の下でデータベース (DB) サーバをDMZから内部ネットワークに移動するような次のネットワーク構成の変更を計画している。このとき、ステートフルパケットフィルタリング型のファイアウォール (FW) において、必要となるフィルタリングルールの変更のうちの一つはどれか。\n\n〔条件]\n(1) Web アプリケーション (WebAP) サーバを、インターネットに公開し, HTTPS でアクセスできるようにする。\n(2) WebAP サーバ上のプログラムだけが DB サーバ上の DB に接続でき, ODBC (Open Database Connectivity) を使用して特定のポート間で通信する。\n(3) SSHを使用して各サーバに接続できるのは、運用管理PCだけである。\n(4) フィルタリングルールは、必要な通信だけを許可する設定にする。\n\n〔構成変更〕変更前はWebAP・DBがDMZのL2スイッチ配下、運用管理PCが内部ネットワークのL3スイッチ配下にある。FWはインターネット・DMZ・内部ネットワークの間にある。変更後はDBを運用管理PCと同じ内部ネットワークのL3スイッチ配下へ移す。"
  },
  "sc-2023h-am1-q7": {
    "explanation": "入力を二つとも同じ信号に接続したNAND素子は、¬(X・X)＝¬Xとなり、NOTとして働きます。図の上側と下側からはそれぞれ¬Xと¬Yが出力され、最後のNANDでZ＝¬(¬X・¬Y)となります。ド・モルガンの法則を適用するとZ＝X＋Yなので、イが正解です。入力00では0、01・10・11では1となり、ORの真理値表とも一致します。途中のNANDが単なるANDではなく出力を否定することと、同じ信号を二入力に入れる構成に注意します。",
    "question": "NAND素子を用いた次の組合せ回路の出力Zを表す式はどれか。ここで、・は論理積、＋は論理和、¬XはXの否定を表す。\n〔回路〕Xを上側のNAND素子の2入力へ、Yを下側のNAND素子の2入力へ、それぞれ同時に接続する。この2素子の出力を最後のNAND素子の2入力へ接続し、Zを出力する。",
    "choices": {
      "ア": "X・Y",
      "イ": "X＋Y",
      "ウ": "¬(X・Y)",
      "エ": "¬(X＋Y)"
    }
  },
