  "sc-2023h-am1-q9": {
    "explanation": "図のaは一つの部門に対応する所属履歴の件数です。部門には必ず1人以上が所属し、その所属を記録するので最低1件、社員や異動が増えれば複数件となり1..*です。bは一人の社員に対応する所属履歴の件数で、必ずいずれかの部門に所属するので最低1件あり、異動履歴も残すため上限は1件ではありません。したがってa・bとも1..*のエが正解です。「社員は一つの部門に所属する」は現在の所属の条件であり、過去を含む所属履歴の件数を1に限定するものではありません。",
    "question": "UML を用いて表した図のデータモデルのa, bに入れる多重度はどれか。\n〔条件〕(1)部門には1人以上の社員が所属する。(2)社員はいずれか一つの部門に所属する。(3)社員が部門に所属した履歴を所属履歴として記録する。\n〔図〕部門（部門コード・部門名…）1 ─ a 所属履歴（開始日・終了日…）b ─ 1 社員（社員コード・氏名…）。aは一つの部門に対する所属履歴の多重度、bは一人の社員に対する所属履歴の多重度。"
  },
