    "question": "UML を用いて表した図のデータモデルのa, bに入れる多重度はどれか。\n〔条件〕(1)部門には1人以上の社員が所属する。(2)社員はいずれか一つの部門に所属する。(3)社員が部門に所属した履歴を所属履歴として記録する。\n〔図〕部門（部門コード・部門名…）1 ─ a 所属履歴（開始日・終了日…）b ─ 1 社員（社員コード・氏名…）。aは一つの部門に対する所属履歴の多重度、bは一人の社員に対する所属履歴の多重度。"
