  "sc-2023h-am1-q19": {
    "explanation": "求めるのは日数なので工数比ではなく期間比を使います。要件定義から内部設計までの期間比は0.25＋0.21＋0.11＝0.57で、これが228日に相当するため全体期間は228／0.57＝400日です。プログラム開発は200本中100本が完了し、各プログラムの期間が同じなので、残りは開発期間の半分です。残期間比は0.11／2＋0.11＋0.21＝0.375となり、400×0.375＝150日です。よってイが正解です。工数と経過期間の配分を混同しないようにします。",
    "question": "過去のプロジェクトの開発実績に基づいて構築した作業配分モデルがある。システム要件定義からシステム内部設計までをモデルどおりに進めて228日で完了し、プログラム開発を開始した。現在,200本のプログラムのうち 100本のプログラムの開発を完了し、残りの100本は未着手の状況である。プログラム開発以降もモデルどおりに進捗すると仮定するとき、プロジェクトの完了まで、あと何日掛かるか。ここで、プログラムの開発に掛かる工数及び期間は、全てのプログラムで同一であるものとする。\n〔作業配分モデル〕工程は要件定義、外部設計、内部設計、プログラム開発、システム結合、システムテストの順。工数比は0.17、0.21、0.16、0.16、0.11、0.19。期間比は0.25、0.21、0.11、0.11、0.11、0.21。"
  },
