  "sc-2024a-am1-q1": {
    "explanation": "交差検証は、データを複数のグループに分割し、学習用と評価用の役割を入れ替えながら学習・評価を繰り返す方法です。特定の一回の分割に評価が左右されにくくなり、未知データに対する汎化性能の推定に使えるため、エが正解です。アは複雑さへのペナルティを加える正則化、イは複数モデルを組み合わせるアンサンブル学習、ウは関連する課題を同時に学ぶマルチタスク学習です。交差検証そのものが学習モデルの出力を多数決で統合する方式なのではありません。"
  },
