  "sc-2024a-am1-q7": {
    "explanation": "コンパイラでは、まず字句解析で文字列を識別子や演算子などのトークンに分け、構文解析で文法的な構造を調べます。続く意味解析では型の整合性や宣言との対応などを確認します。その後、中間表現に対して不要な計算を除くなどの最適化を行い、目的コードの生成につなげるため、この選択肢の中で最後なのはウです。最適化ではプログラムの意味を保ったまま実行時間やコード量の改善を目指します。文法を調べる構文解析と、処理を効率化する最適化を区別します。"
  },
