  "sc-2024a-am1-q20": {
    "explanation": "RTOは中断から復旧までに許容する時間、RLOは復旧させるサービスの範囲や処理能力などの水準です。エでは「中断から1日以内」がRTO、「重要なサービスに限定」がRLOに当たるので正解です。RPOはどの時点のデータまで戻すかを示し、中断する何時間前などと表します。アはRPOとRLO、ウはRTOとRPOの組合せです。イの中断直前へのデータ復旧はRPOですが、営業時間の延長は復旧時間や復旧レベルそのものの目標ではありません。"
  },
