  "sc-2024a-am1-q28": {
    "explanation": "まず製品Aは300個出荷するうち100個の在庫を使うため、新たな製造は200個です。そのためのaは200×3＝600個必要ですが、在庫100個を引いて500個製造します。bはAの製造に直接200×2＝400個、aの製造に500×1＝500個必要なので総所要量は900個です。ここからb自身の在庫300個を引くと正味所要量は600個となり、イが正解です。完成品や中間部品の在庫を先に差し引き、下位部品へ順に展開することで二重計上を防ぎます。",
    "question": "構成表の製品Aを300個出荷しようとするとき、部品bの正味所要量は何個か。ここで、A, a, b, c の在庫量は在庫表のとおりとする。また、他の仕掛残,注文残,引当残などはないものとする。\n〔構成表〕A1個にa3個・b2個・c0個を使用する。a1個にb1個・c2個を使用する。\n〔在庫表：個〕A＝100、a＝100、b＝300、c＝400。"
  },
