  "sc-2024h-am1-q8": {
    "explanation": "アウトラインフォントは、文字の輪郭を直線や曲線の情報として保持し、表示するサイズに合わせて描画します。このため拡大しても元の画素の角が目立つような劣化を抑えられ、任意の倍率で表示するエが適しています。ビットマップフォントは特定サイズの点の配置を保持するので、そのサイズでの表示は簡単ですが、大幅な拡大には不向きです。漢字の有無や等幅かどうかは両形式で実現できるため、アやイは形式を選ぶ決め手ではありません。"
  },
