  "sc-2024h-am1-q17": {
    "explanation": "ゴンペルツ曲線は、初めは緩やかに増え、その後増加が速まり、最後は増加が鈍って一定値に近づくS字形の曲線です。テストの進行に伴う累積バグ検出数をこの形でモデル化し、後半の収束傾向を確認するため、ウが正解です。アは増加が加速し続け、イは一定の割合で直線的に増え、エは最初から増加率が減り続ける形です。ただし検出数が頭打ちになっただけでバグが全て除去されたとは限りません。テストの網羅性や未実施項目も併せて品質を判断します。",
    "choices": {
      "ア": "累積誤り検出数が、初めは緩やかで次第に増加を加速する曲線。",
      "イ": "累積誤り検出数が、テスト項目消化数に対して直線的に増加するグラフ。",
      "ウ": "累積誤り検出数が、初めは緩やか、途中は急増、最後は増加が鈍って一定値に近づくS字形の曲線。",
      "エ": "累積誤り検出数が、初めは急増し、その後は一貫して増加率が小さくなる曲線。"
    }
  },
