  "sc-2024h-am2-q1": {
    "explanation": "CSRFは、ログイン済み利用者のブラウザを悪用して、本人が意図しない正規形式のリクエストを送る攻撃です。攻撃に「<」や「>」は必須ではないため、これらを文字参照へ置換してもリクエストが本人の意思によるかを確認できず、エは対策になりません。アの重要操作時の再認証、イの予測困難なトークン照合、ウの適切なReferer検査は正規の操作との区別に役立ちます。HTMLエスケープは主にXSS対策で、表示先の文脈に応じて出力時に行うものです。",
    "choices": {
      "ア": "Web サイトでの決済などの重要な操作の都度、利用者のパスワードを入力させる。",
      "イ": "Web サイトへのログイン後、毎回異なる値を HTTP レスポンスボディに含め、Web ブラウザからのリクエストごとに送付されるその値を, Web サーバ側で照合する。",
      "ウ": "Web ブラウザからのリクエスト中の Referer によって正しいリンク元からの遷移であることを確認する。",
      "エ": "WebブラウザからのリクエストをWebサーバで受け付けた際に、リクエストに含まれる「<」「>」などの特殊文字を、「&lt;」「&gt;」などの文字列に置き換える。"
    }
  },
  "sc-2024h-am2-q2": {
    "explanation": "MACは送受信者で共有する共通鍵とメッセージから生成します。受信者は同じ鍵で再計算して照合でき、完全性の確認に使えるためアが正解です。第三者は共通鍵を知らないので検証できず、受信者も同じMACを生成できるため、第三者に送信者本人の作成であると証明する用途には使えません。公開鍵を使ってMACを生成するとするウとエも誤りです。公開鍵で検証できるデジタル署名と、秘密の共通鍵を知る当事者間で検証するMACの違いがポイントです。"
  },
  "sc-2025a-am1-q6": {
    "explanation": "LRUはLeast Recently Usedの略で、最後に参照されてから最も長く使われていないブロックを置換します。最終参照時刻はC0が0:08、C1が0:06、C2が0:05、C3が0:10なので、最も古いC2を選ぶエが正解です。FIFOならロード時刻が最も早いC0、LFUなら参照回数が最少のC1、LIFOなら最後にロードされたC3です。ロード時刻、最後に使った時刻、使用回数は異なる情報であり、どれを比較するアルゴリズムかを確かめます。",
    "question": "4ブロックのキャッシュメモリ CO~C3が表に示す状態である。ここで、新たに別 のブロックの内容をキャッシュメモリにロードする必要が生じたとき、C2 のブロッ クを置換の対象とするアルゴリズムはどれか。\n〔表〕列はロード時刻（分:秒）、最終参照時刻（分:秒）、参照回数。C0：0:00、0:08、10。C1：0:03、0:06、1。C2：0:04、0:05、3。C3：0:05、0:10、5。"
  },
