  "sc-2025a-am1-q14": {
    "explanation": "真正性は、対象が主張どおりの本人・正規のものである性質であり、定義bに対応します。信頼性は、意図した行動とその結果が一貫する性質なのでaです。よって真正性b、信頼性aを組み合わせたアが正解です。cは許可された利用者が必要なときに利用できる可用性、dは許可されていない者に情報を使わせたり開示したりしない機密性を表します。「信頼できる」という日常語だけで曖昧に考えず、なりすましの防止と、期待どおりに動くことを分けて整理します。"
  },
