    "question": "マイコンと、表に示す二つのセンサーとを I²C で接続した。センサーからマイコンへのデータの読込みは、センサーアドレス,内部アドレス、センサーアドレスの順にアドレスを送信した後に行う。最初のセンサーアドレスは対象センサーアドレスを左に1ビットシフトして,LSBを0にしたものであり、二つ目のセンサーアドレスは対象センサーアドレスを左に1ビットシフトして LSBを1にしたものである。4A,01,4B の順にアドレスを送信したときにマイコンに読み込まれるデータはどれか。ここで、リスタートコンディションは自動的に行われるものとし、アドレスは 16進数表記である。\n\n〔センサー／センサーアドレス／内部アドレス／データ〕\nジャイロセンサー／25／00／X軸角速度\nジャイロセンサー／25／01／Y軸角速度\n加速度センサー／2A／00／X軸加速度\n加速度センサー／2A／01／Y軸加速度",
