    "explanation": "処理Bの時点では、Xは入力用セマフォiを取得済みで、出力用oはまだ取得していません。ここでYへ切り替わると、Yはoを取得した後、Xが持つiを待って停止します。Xが再開しても、次に必要なoはYが持っているため停止し、互いの解放を待つデッドロックになります。したがってイです。AではXがどちらも持たずYが完了できます。CとDではXが両方を持つので、Yは最初のoの取得で待ち、再開したXが処理を終えて両方を解放できます。",
    "question": "優先度に基づくプリエンプティブスケジューリングのリアルタイム OS を使用した組込みシステムにおいて、入力装置及び出力装置にアクセスする二つのタスク X, Y がある。XはYより優先度が低く、Xが資源待ち状態でない場合にYが資源待ち状態に遷移するとXが実行状態に遷移する。入力装置及び出力装置へのアクセスを排他制御するために、入力装置及び出力装置にそれぞれバイナリセマフォi及びoを用意し,X, Y を図のように実装したとき、デッドロックが発生するのはXの処理 A,B,C又はDのうち、どの処理中にプリエンプションが発生してYが実行されたときか。ここで、Yの実行はαから行うものとし、Xの処理 A, B, C及びDでは入力装置及び出力装置へのアクセス及びバイナリセマフォの操作は行わないものとする。"
